49	Status CommEngine::TransferSync(const AscendString &remote_engine, TransferOp operation,
50	                                const std::vector<TransferOpDesc> &op_descs, int32_t timeout_in_millis) {
51	  HIXL_CHK_BOOL_RET_STATUS(!op_descs.empty(), PARAM_INVALID, "[CommEngine] TransferSync failed, op_descs is empty.");
52	  adxl::TransferOp adxl_operation = static_cast<adxl::TransferOp>(operation);
53	  std::vector<adxl::TransferOpDesc> adxl_op_descs;
54	  for (const auto &op_desc : op_descs) {
55	    adxl_op_descs.emplace_back(adxl::TransferOpDesc{op_desc.local_addr, op_desc.remote_addr, op_desc.len});
56	  }
