61	                                 const std::vector<TransferOpDesc> &op_descs, const TransferArgs &optional_args,
62	                                 TransferReq &req) {
63	  HIXL_CHK_BOOL_RET_STATUS(!op_descs.empty(), PARAM_INVALID, "[CommEngine] TransferAsync failed, op_descs is empty.");
64	  (void)optional_args;
65	  adxl::TransferOp adxl_operation = static_cast<adxl::TransferOp>(operation);
66	  std::vector<adxl::TransferOpDesc> adxl_op_descs;
67	  for (const auto &op_desc : op_descs) {
68	    adxl_op_descs.emplace_back(adxl::TransferOpDesc{op_desc.local_addr, op_desc.remote_addr, op_desc.len});
69	  }
70	  adxl::TransferArgs adxl_optional_args;
71	  return adxl_inner_engine_.TransferAsync(remote_engine, adxl_operation, adxl_op_descs, adxl_optional_args, req);
72	}
73	
74	Status CommEngine::GetTransferStatus(const TransferReq &req, TransferStatus &status) {
75	  adxl::TransferStatus adxl_status;
76	  auto ret = adxl_inner_engine_.GetTransferStatus(req, adxl_status);
77	  status = static_cast<hixl::TransferStatus>(adxl_status);
78	  return ret;
79	}
80	
81	Status CommEngine::GetTransferStatus(const GetTransferStatusArgs &args, std::vector<TransferResult> &results) {
82	  (void)args;
83	  (void)results;
84	  return UNSUPPORTED;
85	}
86	
87	Status CommEngine::SendNotify(const AscendString &remote_engine, const NotifyDesc &notify, int32_t timeout_in_millis) {
88	  adxl::NotifyDesc adxl_notify{notify.name, notify.notify_msg};
89	  return adxl_inner_engine_.SendNotify(remote_engine, adxl_notify, timeout_in_millis);
90	}
91	
92	Status CommEngine::GetNotifies(std::vector<NotifyDesc> &notifies) {
93	  std::vector<adxl::NotifyDesc> adxl_notifies;
94	  auto ret = adxl_inner_engine_.GetNotifies(adxl_notifies);
95	  for (const auto &adxl_notify : adxl_notifies) {
96	    notifies.emplace_back(NotifyDesc{adxl_notify.name, adxl_notify.notify_msg});
97	  }
98	  return ret;
99	}
100	
