193	Status HixlServer::ProcessNotifyMsg(int32_t fd, const char *msg, uint64_t msg_len) {
194	  NotifyMsg notify_msg{};
195	  try {
196	    notify_msg = ParseNotifyMsg(msg, msg_len);
197	  } catch (const nlohmann::json::exception &e) {
198	    HIXL_LOGE(PARAM_INVALID, "Failed to parse NotifyMsg, exception:%s", e.what());
199	    return PARAM_INVALID;
200	  }
201	  Status result = SUCCESS;
202	  {
203	    std::lock_guard<std::mutex> lock(notify_mutex_);
204	    if (notify_messages_.size() >= kMaxNotifyQueueSize) {
205	      HIXL_LOGE(RESOURCE_EXHAUSTED, "Notify queue is full, size:%zu, max:%zu", notify_messages_.size(),
206	                kMaxNotifyQueueSize);
207	      result = RESOURCE_EXHAUSTED;
208	    } else if (notify_msg.name.size() > kMaxNotifyNameLen) {
209	      HIXL_LOGE(PARAM_INVALID, "Notify name length invalid, size:%zu, max:%zu", notify_msg.name.size(),
210	                kMaxNotifyNameLen);
211	      result = PARAM_INVALID;
212	    } else if (notify_msg.notify_msg.size() > kMaxNotifyMsgLen) {
213	      HIXL_LOGE(PARAM_INVALID, "Notify message too long, size:%zu, max:%zu", notify_msg.notify_msg.size(),
214	                kMaxNotifyMsgLen);
215	      result = PARAM_INVALID;
216	    } else {
217	      NotifyDesc notify_desc;
218	      notify_desc.name = AscendString(notify_msg.name.c_str());
219	      notify_desc.notify_msg = AscendString(notify_msg.notify_msg.c_str());
220	      notify_messages_.push_back(notify_desc);
221	    }
222	  }
223	  std::string ack_str;
224	  try {
225	    ack_str = SerializeNotifyAck(result);
226	  } catch (const nlohmann::json::exception &e) {
227	    HIXL_LOGE(FAILED, "Failed to serialize NotifyAck, exception:%s", e.what());
228	    return FAILED;
229	  }
230	  CtrlMsgHeader header{};
231	  header.magic = kMagicNumber;
232	  header.body_size = static_cast<uint64_t>(sizeof(CtrlMsgType) + ack_str.size());
233	  CtrlMsgType msg_type = CtrlMsgType::kNotifyAck;
234	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, &header, static_cast<uint64_t>(sizeof(header))));
235	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, &msg_type, static_cast<uint64_t>(sizeof(msg_type))));
236	  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, ack_str.c_str(), static_cast<uint64_t>(ack_str.size())));
237	  HIXL_LOGI("Received NotifyMsg and sent NotifyAck, name:%s", notify_msg.name.c_str());
238	  return result;
239	}
