245	    const auto &addr_info = kv.second;
246	    MemInfo mi{};
247	    mi.type = addr_info.mem_type;
248	    mi.addr = addr_info.start_addr;
249	    mi.size = addr_info.end_addr - addr_info.start_addr;
250	    result.push_back(mi);
251	  }
252	  return result;
253	}
