255	Status HixlServer::RegisterProcessors() {
256	  MsgProcessor send_endpoint_cb = [this](int32_t fd, const char *msg, uint64_t msg_len) -> Status {
257	    (void)msg;
258	    (void)msg_len;
259	    std::string msg_str;
260	    HIXL_CHK_STATUS_RET(EndpointGenerator::SerializeEndpointConfigList(data_endpoint_config_list_, msg_str),
261	                        "Failed to serialize endpoint config.");
262	    CtrlMsgHeader header{};
263	    header.magic = kMagicNumber;
264	    header.body_size = static_cast<uint64_t>(sizeof(CtrlMsgType) + msg_str.size());
265	    CtrlMsgType msg_type = CtrlMsgType::kGetEndpointInfoResp;
266	    HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, &header, static_cast<uint64_t>(sizeof(header))));
267	    HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, &msg_type, static_cast<uint64_t>(sizeof(msg_type))));
268	    HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, msg_str.c_str(), static_cast<uint64_t>(msg_str.size())));
269	    return SUCCESS;
270	  };
271	  HIXL_CHK_STATUS_RET(HixlCSServerRegProc(server_handle_, CtrlMsgType::kGetEndpointInfoReq, send_endpoint_cb),
272	                      "Failed to register send endpoint info processor.");
273	
274	  MsgProcessor send_mem_info_cb = [this](int32_t fd, const char *msg, uint64_t msg_len) -> Status {
275	    (void)msg;
276	    (void)msg_len;
277	    std::vector<MemInfo> mem_info = GetRegisteredMemInfo();
278	    std::string msg_str;
279	    HIXL_CHK_STATUS_RET(SerializeMemInfoList(mem_info, msg_str), "Failed to serialize mem info list.");
280	    CtrlMsgHeader header{};
281	    header.magic = kMagicNumber;
282	    header.body_size = static_cast<uint64_t>(sizeof(CtrlMsgType) + msg_str.size());
283	    CtrlMsgType msg_type = CtrlMsgType::kGetMemInfoResp;
284	    HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, &header, static_cast<uint64_t>(sizeof(header))));
285	    HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, &msg_type, static_cast<uint64_t>(sizeof(msg_type))));
286	    HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, msg_str.c_str(), static_cast<uint64_t>(msg_str.size())));
287	    return SUCCESS;
288	  };
289	  HIXL_CHK_STATUS_RET(HixlCSServerRegProc(server_handle_, CtrlMsgType::kGetMemInfoReq, send_mem_info_cb),
290	                      "Failed to register send mem info processor.");
291	  MsgProcessor heartbeat_cb = [](int32_t fd, const char *msg, uint64_t msg_len) -> Status {
292	    (void)fd;
293	    (void)msg;
294	    (void)msg_len;
295	    return SUCCESS;
296	  };
297	  HIXL_CHK_STATUS_RET(HixlCSServerRegProc(server_handle_, CtrlMsgType::kHeartBeat, heartbeat_cb),
298	                      "Failed to register heartbeat processor.");
299	  HIXL_CHK_STATUS_RET(RegisterNotifyHandlers(), "Failed to register notify handlers.");
300	  HIXL_CHK_STATUS_RET(HixlCSServerListen(server_handle_, kDefaultBackLog), "HixlServer listen failed, backlog:%u.",
301	                      kDefaultBackLog);
302	  return SUCCESS;
303	}
