namespace hixl {
namespace {
constexpr uint32_t kDefaultBackLog = 1024U;

Status SerializeMemInfoList(const std::vector<MemInfo> &list, std::string &msg_str) {
  nlohmann::json j = nlohmann::json::array();
  try {
    for (const auto &mi : list) {
      nlohmann::json item;
      item["type"] = mi.type;
      item["addr"] = mi.addr;
      item["size"] = mi.size;
      j.push_back(item);
    }
    msg_str = j.dump();
  } catch (const nlohmann::json::exception &e) {
    HIXL_LOGE(PARAM_INVALID, "Failed to dump mem info list, exception:%s", e.what());
    return PARAM_INVALID;
  }
  return SUCCESS;
}

NotifyMsg ParseNotifyMsg(const char *msg, uint64_t msg_len) {
  NotifyMsg notify_msg;
  auto j = nlohmann::json::parse(std::string(msg, msg_len));
  j.at("name").get_to(notify_msg.name);
  j.at("notify_msg").get_to(notify_msg.notify_msg);
  return notify_msg;
}

std::string SerializeNotifyAck(Status result) {
  nlohmann::json j{{"result", result}};
  return j.dump();
}
}  // namespace

Status HixlServer::Initialize(const std::string &ip, int32_t port,
                              const std::vector<EndpointConfig> &data_endpoint_config_list,
                              std::optional<uint32_t> listen_port, std::optional<uint32_t> max_active_channels) {
  data_endpoint_config_list_ = data_endpoint_config_list;
  std::vector<EndpointDesc> data_end_point_list;
  for (const auto &it : data_endpoint_config_list) {
    EndpointDesc end_point_info{};
    HIXL_CHK_STATUS_RET(EndpointGenerator::ConvertToEndpointDesc(it, end_point_info),
                        "Failed to convert endpoint config to endpoint info.");
    data_end_point_list.emplace_back(end_point_info);
  }
  const EndpointDesc *endpoints = data_end_point_list.data();
  if (port < 0) {
    port = 0;
  }
  HixlServerConfig config{};
  std::string global_resource_config;
  if (listen_port.has_value() || max_active_channels.has_value()) {
    nlohmann::json json;
    if (listen_port.has_value()) {
      json["comm_resource_config.listen_port"] = listen_port.value();
    }
    if (max_active_channels.has_value()) {
      json["comm_resource_config.max_active_channels"] = max_active_channels.value();
    }
    global_resource_config = json.dump();
    config.global_resource_config = global_resource_config.c_str();
  }
  HixlServerDesc server_desc{};
  server_desc.server_ip = ip.c_str();
  server_desc.server_port = static_cast<uint32_t>(port);
  server_desc.endpoint_list = endpoints;
  server_desc.endpoint_list_num = static_cast<uint32_t>(data_endpoint_config_list.size());
  HIXL_CHK_STATUS_RET(HixlCSServerCreate(&server_desc, &config, &server_handle_),
                      "Failed to create hixl server, ip:%s, port:%d.", ip.c_str(), port);
  if (port > 0) {
    HIXL_CHK_STATUS_RET(RegisterProcessors(), "Failed to register processors.");
  }
  return SUCCESS;
}

Status HixlServer::RegisterMem(const MemDesc &mem, MemType type, MemHandle &mem_handle) {
  HIXL_CHECK_NOTNULL(server_handle_);
  AddrInfo cur_info{};
  cur_info.start_addr = mem.addr;
  HIXL_CHK_BOOL_RET_STATUS(!ge::AddOverflow(mem.addr, mem.len, cur_info.end_addr), PARAM_INVALID,
                           "Address overflow in RegisterMem, addr:0x%lx, len:%lu.", mem.addr, mem.len);
  cur_info.mem_type = type;
  std::lock_guard<std::mutex> lk(mtx_);

  bool is_duplicate = false;
  MemHandle existing_handle = nullptr;
  HIXL_CHK_STATUS_RET(CheckAddrOverlap(cur_info, handle_to_addr_, is_duplicate, existing_handle),
                      "Failed to check address overlap.");
  if (is_duplicate) {
    mem_handle = existing_handle;
    HIXL_LOGI("Memory already registered, returning existing handle:%p", mem_handle);
    return SUCCESS;
  }

  CommMem hccl_mem{};
  hccl_mem.type = (type == MemType::MEM_DEVICE) ? COMM_MEM_TYPE_DEVICE : COMM_MEM_TYPE_HOST;
  hccl_mem.addr = reinterpret_cast<void *>(mem.addr);
  hccl_mem.size = mem.len;
  HIXL_CHK_STATUS_RET(HixlCSServerRegMem(server_handle_, nullptr, &hccl_mem, &mem_handle),
                      "Failed to register mem, addr:0x%lx, size:%lu, type:%d.", mem.addr, mem.len,
                      static_cast<int32_t>(type));
  handle_to_addr_[mem_handle] = cur_info;
  return SUCCESS;
}

Status HixlServer::DeregisterMem(MemHandle &mem_handle) {
  HIXL_CHECK_NOTNULL(server_handle_);
  // 判断mem_handle是否存在
  std::lock_guard<std::mutex> lk(mtx_);
  auto it = handle_to_addr_.find(mem_handle);
  if (it == handle_to_addr_.end()) {
    HIXL_LOGW("mem_handle:%p is not registered.", mem_handle);
    return SUCCESS;
  }
  HIXL_CHK_STATUS_RET(HixlCSServerUnregMem(server_handle_, mem_handle), "Failed to deregister mem, handle:%p.",
                      mem_handle);
  handle_to_addr_.erase(it);
  mem_handle = nullptr;
  return SUCCESS;
}

Status HixlServer::Finalize() {
  if (server_handle_ == nullptr) {
    return SUCCESS;
  }
  // 注销所有注册的内存
  std::lock_guard<std::mutex> lk(mtx_);
  for (const auto &handle : handle_to_addr_) {
    Status ret = HixlCSServerUnregMem(server_handle_, handle.first);
    if (ret != SUCCESS) {
      HIXL_LOGE(ret, "Failed to deregister mem, handle:%p.", handle);
    }
  }
  handle_to_addr_.clear();
  HIXL_CHK_STATUS_RET(HixlCSServerDestroy(server_handle_), "Failed to destroy hixl server.");
  server_handle_ = nullptr;
  return SUCCESS;
}

Status HixlServer::RegisterCallbackProcessor(int32_t msg_type, CallbackProcessor processor) const {
  MsgProcessor callback = [this, processor, msg_type](int32_t fd, const char *msg, uint64_t msg_len) -> Status {
    bool keep_fd = false;
    HIXL_CHK_STATUS_RET(processor(fd, msg, msg_len, keep_fd), "Failed to process msg, type:%d", msg_type);
    return SUCCESS;
  };
  HIXL_CHK_STATUS_RET(HixlCSServerRegProc(server_handle_, static_cast<CtrlMsgType>(msg_type), callback),
                      "Failed to register send endpoint info processor.");
  return SUCCESS;
}

Status HixlServer::GetNotifies(std::vector<NotifyDesc> &notifies) {
  std::lock_guard<std::mutex> lock(notify_mutex_);
  HIXL_EVENT("HixlServer GetNotifies, count:%zu", notify_messages_.size());
  notifies = std::move(notify_messages_);
  return SUCCESS;
}

Status HixlServer::RegisterNotifyHandlers() {
  MsgProcessor notify_processor = [this](int32_t fd, const char *msg, uint64_t msg_len) -> Status {
    return ProcessNotifyMsg(fd, msg, msg_len);
  };
  HIXL_CHK_STATUS_RET(HixlCSServerRegProc(server_handle_, CtrlMsgType::kNotify, notify_processor),
                      "Failed to register kNotify processor.");
  return SUCCESS;
}

Status HixlServer::ProcessNotifyMsg(int32_t fd, const char *msg, uint64_t msg_len) {
  NotifyMsg notify_msg{};
  try {
    notify_msg = ParseNotifyMsg(msg, msg_len);
  } catch (const nlohmann::json::exception &e) {
    HIXL_LOGE(PARAM_INVALID, "Failed to parse NotifyMsg, exception:%s", e.what());
    return PARAM_INVALID;
  }
  Status result = SUCCESS;
  {
    std::lock_guard<std::mutex> lock(notify_mutex_);
    if (notify_messages_.size() >= kMaxNotifyQueueSize) {
      HIXL_LOGE(RESOURCE_EXHAUSTED, "Notify queue is full, size:%zu, max:%zu", notify_messages_.size(),
                kMaxNotifyQueueSize);
      result = RESOURCE_EXHAUSTED;
    } else if (notify_msg.name.size() > kMaxNotifyNameLen) {
      HIXL_LOGE(PARAM_INVALID, "Notify name length invalid, size:%zu, max:%zu", notify_msg.name.size(),
                kMaxNotifyNameLen);
      result = PARAM_INVALID;
    } else if (notify_msg.notify_msg.size() > kMaxNotifyMsgLen) {
      HIXL_LOGE(PARAM_INVALID, "Notify message too long, size:%zu, max:%zu", notify_msg.notify_msg.size(),
                kMaxNotifyMsgLen);
      result = PARAM_INVALID;
    } else {
      NotifyDesc notify_desc;
      notify_desc.name = AscendString(notify_msg.name.c_str());
      notify_desc.notify_msg = AscendString(notify_msg.notify_msg.c_str());
      notify_messages_.push_back(notify_desc);
    }
  }
  std::string ack_str;
  try {
    ack_str = SerializeNotifyAck(result);
  } catch (const nlohmann::json::exception &e) {
    HIXL_LOGE(FAILED, "Failed to serialize NotifyAck, exception:%s", e.what());
    return FAILED;
  }
  CtrlMsgHeader header{};
  header.magic = kMagicNumber;
  header.body_size = static_cast<uint64_t>(sizeof(CtrlMsgType) + ack_str.size());
  CtrlMsgType msg_type = CtrlMsgType::kNotifyAck;
  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, &header, static_cast<uint64_t>(sizeof(header))));
  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, &msg_type, static_cast<uint64_t>(sizeof(msg_type))));
  HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, ack_str.c_str(), static_cast<uint64_t>(ack_str.size())));
  HIXL_LOGI("Received NotifyMsg and sent NotifyAck, name:%s", notify_msg.name.c_str());
  return result;
}

std::vector<MemInfo> HixlServer::GetRegisteredMemInfo() const {
  std::lock_guard<std::mutex> lk(mtx_);
  std::vector<MemInfo> result;
  for (const auto &kv : handle_to_addr_) {
    const auto &addr_info = kv.second;
    MemInfo mi{};
    mi.type = addr_info.mem_type;
    mi.addr = addr_info.start_addr;
    mi.size = addr_info.end_addr - addr_info.start_addr;
    result.push_back(mi);
  }
  return result;
}

Status HixlServer::RegisterProcessors() {
  MsgProcessor send_endpoint_cb = [this](int32_t fd, const char *msg, uint64_t msg_len) -> Status {
    (void)msg;
    (void)msg_len;
    std::string msg_str;
    HIXL_CHK_STATUS_RET(EndpointGenerator::SerializeEndpointConfigList(data_endpoint_config_list_, msg_str),
                        "Failed to serialize endpoint config.");
    CtrlMsgHeader header{};
    header.magic = kMagicNumber;
    header.body_size = static_cast<uint64_t>(sizeof(CtrlMsgType) + msg_str.size());
    CtrlMsgType msg_type = CtrlMsgType::kGetEndpointInfoResp;
    HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, &header, static_cast<uint64_t>(sizeof(header))));
    HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, &msg_type, static_cast<uint64_t>(sizeof(msg_type))));
    HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, msg_str.c_str(), static_cast<uint64_t>(msg_str.size())));
    return SUCCESS;
  };
  HIXL_CHK_STATUS_RET(HixlCSServerRegProc(server_handle_, CtrlMsgType::kGetEndpointInfoReq, send_endpoint_cb),
                      "Failed to register send endpoint info processor.");

  MsgProcessor send_mem_info_cb = [this](int32_t fd, const char *msg, uint64_t msg_len) -> Status {
    (void)msg;
    (void)msg_len;
    std::vector<MemInfo> mem_info = GetRegisteredMemInfo();
    std::string msg_str;
    HIXL_CHK_STATUS_RET(SerializeMemInfoList(mem_info, msg_str), "Failed to serialize mem info list.");
    CtrlMsgHeader header{};
    header.magic = kMagicNumber;
    header.body_size = static_cast<uint64_t>(sizeof(CtrlMsgType) + msg_str.size());
    CtrlMsgType msg_type = CtrlMsgType::kGetMemInfoResp;
    HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, &header, static_cast<uint64_t>(sizeof(header))));
    HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, &msg_type, static_cast<uint64_t>(sizeof(msg_type))));
    HIXL_CHK_STATUS_RET(CtrlMsgPlugin::Send(fd, msg_str.c_str(), static_cast<uint64_t>(msg_str.size())));
    return SUCCESS;
  };
  HIXL_CHK_STATUS_RET(HixlCSServerRegProc(server_handle_, CtrlMsgType::kGetMemInfoReq, send_mem_info_cb),
                      "Failed to register send mem info processor.");
  MsgProcessor heartbeat_cb = [](int32_t fd, const char *msg, uint64_t msg_len) -> Status {
    (void)fd;
    (void)msg;
    (void)msg_len;
    return SUCCESS;
  };
  HIXL_CHK_STATUS_RET(HixlCSServerRegProc(server_handle_, CtrlMsgType::kHeartBeat, heartbeat_cb),
                      "Failed to register heartbeat processor.");
  HIXL_CHK_STATUS_RET(RegisterNotifyHandlers(), "Failed to register notify handlers.");
  HIXL_CHK_STATUS_RET(HixlCSServerListen(server_handle_, kDefaultBackLog), "HixlServer listen failed, backlog:%u.",
                      kDefaultBackLog);
  return SUCCESS;
}

